def sprawdz_parametry(params):
    for param in params:
        if param.name not in ('max_speed', 'arrival_radius'):
            continue
        if param.type_ != Parameter.Type.DOUBLE or not math.isfinite(param.value):
            return SetParametersResult(successful=False, reason=f'{param.name}: potrzebuję skończonej liczby DOUBLE')
        if param.name == 'max_speed' and not 0 < param.value <= 2.0:
            return SetParametersResult(successful=False, reason='max_speed musi być w zakresie (0, 2]')
        if param.name == 'arrival_radius' and not 0.1 <= param.value <= 1.0:
            return SetParametersResult(successful=False, reason='arrival_radius musi być w zakresie [0.1, 1]')
    return SetParametersResult(successful=True)

proby = [
    ([Parameter('max_speed', value=0.6), Parameter('arrival_radius', value=0.4)], True),
    ([Parameter('max_speed', value=0.0)], False),
    ([Parameter('max_speed', value=2.1)], False),
    ([Parameter('max_speed', value=float('nan'))], False),
    ([Parameter('max_speed', value=1)], False),
    ([Parameter('arrival_radius', value=0.09)], False),
    ([Parameter('arrival_radius', value=1.1)], False),
    ([Parameter('arrival_radius', value=float('inf'))], False),
    ([Parameter('max_speed', value=2.0), Parameter('arrival_radius', value=0.1)], True),
    ([Parameter('use_sim_time', value=False)], True),
]
wyniki = [sprawdz_parametry(params).successful for params, expected in proby]
